<?php require_once __DIR__.'/../includes/admin-layout.php';admin_start('Bildirimler');$rows=db()->query('SELECT r.*,i.short_id,i.original_filename,u.email owner_email FROM reports r JOIN images i ON i.id=r.image_id LEFT JOIN users u ON u.id=i.user_id ORDER BY r.id DESC LIMIT 250')->fetchAll();admin_title('GÜVENLİK VE UYUMLULUK','İçerik bildirimleri','Kötüye kullanım ve hak ihlali bildirimlerini görsel sahibiyle birlikte değerlendirin.');?><section class="admin-card table-card"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Görsel</th><th>Neden</th><th>Ayrıntı</th><th>Görsel sahibi</th><th>Durum</th><th>Tarih</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="/<?=e($r['short_id'])?>"><b><?=e($r['original_filename'])?></b><small>/<?=e($r['short_id'])?></small></a></td><td><span class="table-status"><?=e($r['reason'])?></span></td><td class="detail-cell"><?=e($r['details']??'—')?></td><td><?=e($r['owner_email']?:'Anonim')?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div></section><?php admin_end();
